head.b:skin:
/* -----------------------------------------------
Premium Blogger Theme - Modern Layout
Designer : Gemini AI
----------------------------------------------- 
*/

/* Reset & Dasar */
body { background: #f4f7f6; color: #333; font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; margin: 0; padding: 0; line-height: 1.6; }
a { color: #2c3e50; text-decoration: none; transition: 0.3s; }
a:hover { color: #3498db; }

/* Container Utama */
.outer-wrapper { max-width: 1100px; margin: 0 auto; background: #fff; box-shadow: 0 10px 30px rgba(0,0,0,0.05); }

/* Header Premium */
header#header-wrapper { padding: 40px 20px; text-align: center; border-bottom: 1px solid #eee; background: #fff; }
header h1 { font-size: 32px; font-weight: 800; letter-spacing: -1px; text-transform: uppercase; }

/* Navigasi */
#nav-menu { background: #2c3e50; color: #fff; display: flex; justify-content: center; position: sticky; top: 0; z-index: 100; }
#nav-menu ul { list-style: none; padding: 0; margin: 0; display: flex; }
#nav-menu li a { color: #fff; padding: 15px 25px; display: block; font-weight: 600; font-size: 14px; }
#nav-menu li a:hover { background: #3498db; }

/* Main Content */
.main-wrapper { display: flex; flex-wrap: wrap; padding: 20px; }
#main-content { flex: 2; min-width: 300px; padding: 10px; }
#sidebar-wrapper { flex: 1; min-width: 250px; padding: 10px; }

/* Post Style */
.post { margin-bottom: 40px; padding-bottom: 20px; border-bottom: 1px solid #f0f0f0; }
.post-title { font-size: 26px; margin: 10px 0; font-weight: 700; }

/* Premium Widgets */
.abc-container { background: #ecf0f1; padding: 40px 20px; text-align: center; margin-top: 20px; border-radius: 8px; }
.abc h2 { color: #2c3e50; font-weight: 700; }

/* Footer */
footer#footer-wrapper { background: #2c3e50; color: #bdc3c7; padding: 40px 20px; text-align: center; font-size: 13px; }

/* Responsive */
@media (max-width: 768px) {
  .main-wrapper { flex-direction: column; }
  #nav-menu ul { flex-direction: column; width: 100%; text-align: center; }
}
